{
  "preset": "tuan-1b",
  "base_params": 1000000000,
  "max_learned": 2000000000,
  "total_cap": 3000000000,
  "budget": {
    "base_params": 1000000000,
    "learned_params": 0,
    "max_learned": 2000000000,
    "total_cap": 3000000000,
    "remaining_learned": 2000000000,
    "remaining_total": 2000000000,
    "vram_params": 0,
    "learned_share": 0.0
  },
  "doubling": {
    "claim": "上下文翻倍 HBM 增量 <= 1.0 GiB",
    "limit_bytes": 1073741824,
    "stream": {
      "max_delta": 0,
      "holds": true,
      "note": "O(1) 流式状态与 L 无关，翻倍增量恒为 0"
    },
    "chunked": {
      "max_delta": 0,
      "holds": true,
      "note": "分块训练显存只随 chunk 增长，与总 L 无关，增量恒为 0"
    },
    "naive": {
      "fits_hbm_anywhere": false,
      "overflows_from": 524288,
      "note": "整段 FFT 随 L 线性增长（见 overflows_from 起点）—— 不可行，仅作对照"
    },
    "claim_holds": true
  },
  "schedule": {
    "cap_days": 90,
    "allocations": {
      "Phase 0 冻结": 30,
      "Phase 1 · 1B 基座": 30,
      "复盘（立即）": 2,
      "Phase 2 · 2B 附加参数": 28
    },
    "total_days": 90,
    "holds": true,
    "note": "Phase 0/复盘也有硬停——全程 90 天含后端验收，不是只有训练"
  },
  "phases": [
    {
      "name": "Phase 0 冻结",
      "objective": "自研 CUDA/C++ 后端一致性验收（BackendContract）+ 数据 / 分词器 / 配置冻结（运行时 = 自研后端；PyTorch 退役出战役路径，torch 实现仅作冻结数值 oracle）",
      "max_days": 30,
      "hard_stop": true,
      "hbm_gib": 18.65,
      "token_budget": null,
      "steps": [
        "后端逐项通过 BackendContract 一致性检查（下闸门自动生成自 conformance_checks）",
        "语料与词表冻结（32000 vocab 口径），文档级无泄漏切分",
        "后端在 512K 上下文跑通 8192-chunk 分块流式训练；实测吞吐/MFU，修正 token 预算",
        "90 天总预算下 Phase 0 不得挤占训练期：第 30 天未过 conformance 即战役重排（砍 8M 档，保 4M）"
      ],
      "gates": [
        {
          "name": "P0-backend-conformance",
          "kind": "hard",
          "criterion": "契约 simplcore-cuda-backend v1.0 全部 16 个内核有实现并通过单元测试"
        },
        {
          "name": "P0-stream-bitexact",
          "kind": "hard",
          "criterion": "FFT 并行形式 vs IIR 流式形式，fp32 下 max|Δ| < 4e-5（4M 长度）"
        },
        {
          "name": "P0-chunked-carry",
          "kind": "hard",
          "criterion": "分块训练的跨块状态携带 与 整段参考 逐位一致"
        },
        {
          "name": "P0-frozen-mask",
          "kind": "hard",
          "criterion": "adamw_frozen_mask 冻结位零更新（基座冻结/适配器预算语义的前提）"
        },
        {
          "name": "P0-bf16-accum",
          "kind": "hard",
          "criterion": "抽样内核验证 fp32 累加（GEMM / rmsnorm / cumsum / ce_loss）"
        },
        {
          "name": "P0-shard-2gcd",
          "kind": "hard",
          "criterion": "2 GCD 切分下训练数值与单卡一致（all-reduce fp32）"
        },
        {
          "name": "P0-no-attention",
          "kind": "hard",
          "criterion": "内核清单结构审查：零注意力 / 零 KV cache / 零位置表"
        },
        {
          "name": "P0-budget-frozen",
          "kind": "hard",
          "criterion": "数据/分词器/配置冻结并记录哈希，之后不得更改"
        },
        {
          "name": "P0-hard-stop-30d",
          "kind": "hard",
          "criterion": "到 30 天硬停：conformance 未全过即触发降档预案（8M→4M），训练期不动"
        }
      ]
    },
    {
      "name": "Phase 1 · 1B 基座",
      "objective": "1B 基座训练完成（4M 上下文学习），单张 MI250，最长 30 天，到点硬停",
      "max_days": 30,
      "hard_stop": true,
      "hbm_gib": 18.65,
      "token_budget": 26595846220.15797,
      "steps": [
        "上下文课程：1M → 2M → 4M 逐级翻倍，每级稳定后升级",
        "每周 checkpoint + held-out loss 曲线留档",
        "第 4 周起转入 4M 长上下文主训"
      ],
      "gates": [
        {
          "name": "P1-chunked-4m-nooom",
          "kind": "hard",
          "criterion": "4M 上下文分块训练在 128 GB HBM 内 OOM-free（解析估算 18.7 GiB）"
        },
        {
          "name": "P1-doubling-claim",
          "kind": "hard",
          "criterion": "实测上下文翻倍 HBM 增量 ≤ 1.0 GiB（解析预期 0）"
        },
        {
          "name": "P1-stream-bitexact-4m",
          "kind": "hard",
          "criterion": "4M 长度下 流式==并行 逐位一致"
        },
        {
          "name": "P1-loss-stable",
          "kind": "hard",
          "criterion": "held-out loss 曲线稳定无发散"
        },
        {
          "name": "P1-token-budget",
          "kind": "soft",
          "criterion": "喂满解析 token 预算 ~26.6B（MFU 实测后修正）"
        },
        {
          "name": "P1-hard-stop-30d",
          "kind": "hard",
          "criterion": "到 30 天强制冻结最优 checkpoint，无条件进入复盘"
        }
      ]
    },
    {
      "name": "复盘（立即）",
      "objective": "基座完成后**立即**复盘自身：失败轨迹 → 总结为训练样本（envlearn.summarize_failures 语义）",
      "max_days": 2,
      "hard_stop": true,
      "hbm_gib": 0.0,
      "token_budget": null,
      "steps": [
        "收集 Phase 1 全部失败/低分轨迹（长上下文检索、代码执行）",
        "总结为少量高价值训练样本（不是原样回放）",
        "产出复盘报告：哪类能力缺失、2B 附加参数优先学什么"
      ],
      "gates": [
        {
          "name": "R-failures-summarized",
          "kind": "hard",
          "criterion": "失败轨迹已总结为训练样本并有清单"
        },
        {
          "name": "R-report-written",
          "kind": "hard",
          "criterion": "复盘报告落盘，明确 2B 阶段的学习优先级"
        },
        {
          "name": "R-hard-stop-2d",
          "kind": "hard",
          "criterion": "复盘 ≤2 天（90 天总预算零余量），超时砍样本量不砍 Phase 2"
        }
      ]
    },
    {
      "name": "Phase 2 · 2B 附加参数",
      "objective": "基座冻结，学习 ≤2B 适配器（总上限 3B），分阶段蒸馏，最长 28 天，多了等不了",
      "max_days": 28,
      "hard_stop": true,
      "hbm_gib": 65.22,
      "token_budget": 10232427376.624218,
      "steps": [
        "LearnedAdapter.grow 按复盘优先级分配 2B 预算（WeightBudget 硬拒超额）",
        "分阶段蒸馏：环境交互 → 总结 → 蒸馏 → 环境验证 → no-regression gate → 退化回滚",
        "每 stage 留档：loss_before/after、pass_rate、是否回滚"
      ],
      "gates": [
        {
          "name": "P2-base-frozen",
          "kind": "hard",
          "criterion": "基座权重逐位未变（快照对比）"
        },
        {
          "name": "P2-budget-cap",
          "kind": "hard",
          "criterion": "适配器 ≤ 2B 且总权重 ≤ 3B（硬拒超额）"
        },
        {
          "name": "P2-no-regression",
          "kind": "hard",
          "criterion": "每个 stage 通过 no-regression gate，退化即回滚"
        },
        {
          "name": "P2-hard-stop-28d",
          "kind": "hard",
          "criterion": "到 28 天硬停，多了等不了，无延期"
        }
      ]
    }
  ],
  "protocol": [
    {
      "name": "X-equal-budget",
      "kind": "hard",
      "criterion": "对照口径：与 3B Transformer 基线**等 token / 等 FLOPs**，禁止无限定宣称"
    },
    {
      "name": "X-heldout-ppl",
      "kind": "hard",
      "criterion": "held-out 困惑度 ≤ 基线 × 1.05（目标值，非承诺；实测为准）"
    },
    {
      "name": "X-longctx-retrieval",
      "kind": "hard",
      "criterion": "1M / 2M / 4M 长上下文检索准确率 ≥ 基线"
    },
    {
      "name": "X-code-passk",
      "kind": "hard",
      "criterion": "代码 pass@k（CodeExecutionVerifier 真实执行）≥ 基线"
    },
    {
      "name": "X-throughput",
      "kind": "hard",
      "criterion": "1M 上下文解码吞吐 ≥ 基线（对方 KV cache ~32 GB vs 我方流式 <1 MB）"
    },
    {
      "name": "X-stream-consistency",
      "kind": "hard",
      "criterion": "全部评测在流式与整段两种模式下结果一致"
    }
  ],
  "showcase": [
    {
      "name": "S1-deploy-2gb",
      "kind": "hard",
      "owner": "Phase 0（账本）+ 实机一条命令",
      "claim": "1M 上下文完整推理 ≤ 2 GiB（1.948 GiB，含权重）",
      "verify": "python -m simplcore.core.deploy_budget"
    },
    {
      "name": "S2-doubling-zero",
      "kind": "hard",
      "owner": "Phase 1",
      "claim": "上下文 1M→8M 翻倍 HBM 增量恒为 0（结构性，非调参）",
      "verify": "python -m simplcore.core.campaign  # 阶梯表 delta 全 0"
    },
    {
      "name": "S3-decode-10x",
      "kind": "hard",
      "owner": "Phase 1",
      "claim": "1M 上下文解码吞吐 ≥ 10× 同卡 TS-3B（KV cache 60 GB vs 流式 30 MiB）",
      "verify": "python -m simplcore.core.scaling  + 后端实机 benchmark"
    },
    {
      "name": "S4-equal-token-ppl",
      "kind": "hard",
      "owner": "Phase 1",
      "claim": "等 token 预算 held-out ppl ≤ TS-2B × 1.05",
      "verify": "对比脚本 + runs/eval_equal_token.json（协议 X-equal-budget）"
    },
    {
      "name": "S5-longctx-4m",
      "kind": "hard",
      "owner": "Phase 1+2",
      "claim": "1M/2M/4M 检索+摘要综合 ≥ YaRN 扩展 TS-5B（§7 轴 C 中位预测）",
      "verify": "评测脚本 + 原始输出留档"
    },
    {
      "name": "S6-evolution-passk",
      "kind": "hard",
      "owner": "Phase 2",
      "claim": "自进化前后代码 pass@k 可验证提升，含 no-regression 回滚记录",
      "verify": "envlearn stage 日志（loss_before/after、pass_rate、rollback）"
    },
    {
      "name": "S7-honest-needle",
      "kind": "honest",
      "owner": "Phase 1",
      "claim": "1M needle 精确召回 < TS-2B —— 信息论边界主动呈现（30.4 MiB 状态 vs ≥2 GB 原文）",
      "verify": "同评测脚本，结果如实入演示包"
    },
    {
      "name": "S8-reproducible",
      "kind": "hard",
      "owner": "全程",
      "claim": "任何人 5 分钟复验数学与账本：848 测试 + 13 证明 + 34 守卫 + 21 CLI",
      "verify": "python -m pytest simplcore -q && python -m simplcore.core.mathproof"
    }
  ],
  "forbidden": [
    "注意力图 / 注意力热图等**机制内部**的对比（用户原话：真实输出结果，而不是注意力层面）",
    "无等 token / 等 FLOPs 口径的无限定'1B 打 3B'宣称",
    "自报自评（无独立 verifier 的自我打分）",
    "只报平均、不报分布与最差 case 的 cherry-picking"
  ]
}
